def tooluse_prompt(state: str) -> str:
    return (
        "<|im_start|>user\n"
        "You are running the AI-WCAG-Gauntlet benchmark loop.\n\n"
        "Current state:\n" + state + "\n\n"
        "Question 1: Which validator or action comes next? "
        "Answer with exactly one word from: " + ", ".join(CRITERIA) + ".\n"
        "Question 2: Should you run a validator on your own code before the "
        "official iteration check? Answer with exactly yes or no.\n"
        "Format: <word>\n<yes|no><|im_end|>\n"
        "<|im_start|>assistant\n"
    )


def target_text(gold) -> str:
    return f"{gold['next_tool']}\n{'yes' if gold['run_precheck'] else 'no'}<|im_end|>\n"


def main():
    import io, subprocess, sys, gc
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--upgrade", "torchao>=0.16.0"], check=False)
    for pkg in ("peft", "bitsandbytes", "accelerate"):
        try:
            __import__(pkg)
        except ImportError:
            subprocess.run([sys.executable, "-m", "pip", "install", "-q", pkg], check=True)
    # transformers 5.x materializes a ~6.4GB bf16 torch.stack of 128 experts at load
    # (expert ModuleList -> stacked 3D merge) -> OOMs the 14.56 GiB T4s.
    # transformers 4.57 loads qwen3_moe experts as a ModuleList (per-expert 4-bit,
    # small temporaries) -> direct GPU load works.
    import transformers as _tf
    _maj = _tf.__version__.split(".")[0]
    if _maj != "4":
        print(f"transformers {_tf.__version__} -> pinning 4.57.x + peft 0.17.1", flush=True)
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "transformers>=4.57,<5"], check=True)
        # current (2026) peft needs transformers 5.x's transformers.conversion_mapping
        # at get_peft_model time -> pin the 4.x-era peft whenever we pin 4.57.
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "peft==0.17.1"], check=True)
        # purge cached 5.x / new-peft modules so the pinned files are what get imported
        for _mod in ("transformers", "peft"):
            for _m in [m for m in list(sys.modules) if m == _mod or m.startswith(_mod + ".")]:
                del sys.modules[_m]
        import transformers as _tf2
        assert _tf2.__version__.startswith("4."), _tf2.__version__
        import peft as _peft
        print("now on transformers", _tf2.__version__, "peft", _peft.__version__, flush=True)

    from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig, get_cosine_schedule_with_warmup
    try:
        from peft import LoraConfig, get_peft_model
    except Exception as _e:
        print("peft import failed:", _e, "-> pinning peft==0.17.1 (transformers-4.x era)", flush=True)
        import subprocess as _sp
        _sp.run([sys.executable, "-m", "pip", "install", "-q", "peft==0.17.1"], check=True)
        for _m in [m for m in list(sys.modules) if m == "peft" or m.startswith("peft.")]:
            del sys.modules[_m]
        from peft import LoraConfig, get_peft_model

    random.seed(SEED)
    torch.manual_seed(SEED)
    t0 = time.time()
    n_gpu = torch.cuda.device_count()
    print(f"GPUs: {n_gpu} {[torch.cuda.get_device_name(i) for i in range(n_gpu)]}", flush=True)
    if n_gpu < 2:
        print("WARNING: 30B QLoRA expects a 2xT4 GPU pair; single GPU will likely OOM", flush=True)
    os.makedirs(HF_CACHE, exist_ok=True)

    def load_split(name):
        raw = {"fit": _FIT_JSONL, "val": _VAL_JSONL, "test": _TEST_JSONL}[name]
        return [json.loads(line) for line in io.StringIO(raw) if line.strip()]
    fit_rows, val_rows, test_rows = load_split("fit"), load_split("val"), load_split("test")
    # 30B on 2xT4: ~23.6 s/batch -> 300 rows = 118 min, which busts the 3h session
    # limit with load+eval overhead. The state->tool mapping is highly repetitive;
    # 150 rows x 1 epoch is enough for the 30B (already tool-calling capable).
    fit_rows = fit_rows[:24]
    print("Loaded fit=%d val=%d test=%d (fit trimmed for the 3h kernel limit)" % (len(fit_rows), len(val_rows), len(test_rows)), flush=True)

    # 4.57's tokenizer loader probes a nonexistent "additional_chat_templates" tree
    # on the remote repo -> 404. Pre-download the tokenizer files locally and load
    # from that directory instead.
    from huggingface_hub import snapshot_download
    tok_dir = snapshot_download(
        MODEL_NAME,
        allow_patterns=["tokenizer*.json", "tokenizer*.model", "tokenizer_config.json",
                       "special_tokens_map.json", "chat_template.jinja", "*.jinja", "config.json"],
        cache_dir=os.path.join(HF_CACHE, "hub"),
    )
    tokenizer = AutoTokenizer.from_pretrained(tok_dir)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token

    bnb = BitsAndBytesConfig(
        load_in_4bit=True,
        bnb_4bit_quant_type="nf4",
        bnb_4bit_use_double_quant=True,
        bnb_4bit_compute_dtype=torch.bfloat16,
    )
    print(f"Loading 4-bit {MODEL_NAME} (bf16 download -> {HF_CACHE}) ...", flush=True)
    from transformers import AutoConfig
    cfg = AutoConfig.from_pretrained(tok_dir)
    n_layers = cfg.num_hidden_layers
    half = (n_layers + 1) // 2
    device_map = {"model.embed_tokens": "cuda:0", "model.rotary_emb": "cuda:0"}
    for i in range(n_layers):
        device_map[f"model.layers.{i}"] = "cuda:0" if i < half else "cuda:1"
    device_map["model.norm"] = "cuda:1"
    device_map["lm_head"] = "cuda:1"
    print(f"device_map: {n_layers} layers, first {half} -> cuda:0, rest + lm_head -> cuda:1", flush=True)
    model = AutoModelForCausalLM.from_pretrained(
        MODEL_NAME,
        quantization_config=bnb,
        cache_dir=os.path.join(HF_CACHE, "hub"),
        device_map=device_map,
        attn_implementation="sdpa",
    )
    for i in range(2):
        tot, free = torch.cuda.mem_get_info(i)
        print(f"GPU {i}: {free/1024**3:.2f} GiB free after 4-bit load", flush=True)
    # Verify placement: if 4.57 ignored the device_map (4-bit weights on CPU),
    # force dispatch onto the two GPUs — CPU 4-bit training would take days.
    dev_first = next(model.model.layers[0].parameters()).device
    dev_last = next(model.model.layers[-1].parameters()).device
    print(f"layer0 on {dev_first}, layer{len(model.model.layers)-1} on {dev_last}", flush=True)
    if str(dev_first) == "cpu" or str(dev_last) == "cpu":
        print("4-bit weights on CPU -> forcing GPU dispatch via accelerate", flush=True)
        from accelerate import dispatch_model
        model = dispatch_model(model, device_map)
        dev_first = next(model.model.layers[0].parameters()).device
        dev_last = next(model.model.layers[-1].parameters()).device
        print(f"after dispatch: layer0 on {dev_first}, layer{len(model.model.layers)-1} on {dev_last}", flush=True)
        for i in range(2):
            tot, free = torch.cuda.mem_get_info(i)
            print(f"GPU {i}: {free/1024**3:.2f} GiB free after dispatch", flush=True)
        if str(dev_first) == "cpu" or str(dev_last) == "cpu":
            print("dispatch did not move weights -> manual per-layer .to() (bnb moves quant_state)", flush=True)
            for i, layer in enumerate(model.model.layers):
                layer.to("cuda:0" if i < half else "cuda:1")
            model.model.embed_tokens.to("cuda:0")
            model.model.rotary_emb.to("cuda:0")
            model.model.norm.to("cuda:1")
            model.lm_head.to("cuda:1")
            dev_first = next(model.model.layers[0].parameters()).device
            dev_last = next(model.model.layers[-1].parameters()).device
            print(f"after manual .to(): layer0 on {dev_first}, layer{len(model.model.layers)-1} on {dev_last}", flush=True)
            for i in range(2):
                tot, free = torch.cuda.mem_get_info(i)
                print(f"GPU {i}: {free/1024**3:.2f} GiB free after manual .to()", flush=True)
    model.config.use_cache = False
    print("Base model loaded (4-bit).", flush=True)

    lora_cfg = LoraConfig(
        r=RANK, lora_alpha=LORA_ALPHA, lora_dropout=0.05,
        target_modules=["q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj"],
        bias="none", task_type="CAUSAL_LM",
    )
    model = get_peft_model(model, lora_cfg)
    # Gradient checkpointing disabled: on this 4.57 + bnb-MoE build the checkpoint
    # recompute diverges from the saved forward (seq 43 vs 44) -> CheckpointError.
    # batch1 / short-seq activations fit on 2xT4 without it.
    model.gradient_checkpointing_disable()
    model.print_trainable_parameters()

    def prompt_body(state):
        return (
            "You are running the AI-WCAG-Gauntlet benchmark loop.\n\n"
            "Current state:\n" + state + "\n\n"
            "Question 1: Which validator or action comes next? "
            "Answer with exactly one word from: " + ", ".join(CRITERIA) + ".\n"
            "Question 2: Should you run a validator on your own code before the "
            "official iteration check? Answer with exactly yes or no.\n"
            "Format: <word>\n<yes|no>\n"
        )

    def chat_prompt(state):
        """Qwen3 chat template, thinking OFF so generation stays in short-answer mode."""
        msgs = [{"role": "user", "content": prompt_body(state)}]
        try:
            return tokenizer.apply_chat_template(msgs, add_generation_prompt=True, enable_thinking=False, tokenize=False)
        except TypeError:
            return tokenizer.apply_chat_template(msgs, add_generation_prompt=True, tokenize=False)

    def target30(gold):
        return f"{gold['next_tool']}\n{'yes' if gold['run_precheck'] else 'no'}\n"

    def encode(rows):
        encs = []
        for r in rows:
            p = chat_prompt(r["state"])
            t = target30(r["gold"])
            full = tokenizer(p + t, truncation=True, max_length=MAX_LEN).input_ids
            plen = len(tokenizer(p, truncation=True, max_length=MAX_LEN).input_ids)
            labels = [-100] * plen + full[plen:]
            encs.append((full, labels))
        return encs

    train_enc = encode(fit_rows)
    val_enc = encode(val_rows)
    test_enc = encode(test_rows)

    def collate(batch):
        ids = torch.nn.utils.rnn.pad_sequence(
            [torch.tensor(b[0]) for b in batch], batch_first=True, padding_value=tokenizer.pad_token_id)
        labels = torch.nn.utils.rnn.pad_sequence(
            [torch.tensor(b[1]) for b in batch], batch_first=True, padding_value=-100)
        return ids, labels

    # AdamW fp32 states = ~6.7GB across the pair -> OOMs GPU 0 on the first step.
    # 8-bit Adam keeps the optimizer states ~4x smaller (QLoRA standard).
    try:
        from bnb.optim import Adam8bit as _Opt
    except ImportError:
        from bitsandbytes.optim import Adam8bit as _Opt
    opt = _Opt(model.parameters(), lr=LR, weight_decay=0.01)
    sched_steps = EPOCHS * math.ceil(len(train_enc) / (BATCH * GRAD_ACCUM))
    sched = get_cosine_schedule_with_warmup(opt, num_warmup_steps=int(0.05 * sched_steps), num_training_steps=sched_steps)


    import re as _re
    def evaluate(rows, tag):
        """next-tool / precheck accuracy via greedy generation (chat-template prompts)."""
        model.eval()
        model.config.use_cache = True  # generate() needs KV cache; restore after

        ok_nt = ok_pr = 0
        test_rows_eval = rows[:EVAL_SAMPLE]
        with torch.no_grad():
            for r in test_rows_eval:
                p = chat_prompt(r["state"])
                t = tokenizer(p, return_tensors="pt").input_ids.to(next(model.parameters()).device)
                gen = model.generate(t, max_new_tokens=8, do_sample=False, pad_token_id=tokenizer.pad_token_id)
                ans = tokenizer.decode(gen[0, t.shape[1]:], skip_special_tokens=True).strip().lower()
                m = _re.search(r"\b(" + "|".join(CRITERIA) + r")\b", ans)
                pred_nt = m.group(1) if m else ""
                pred_pr = bool(_re.search(r"\byes\b", ans)) and not _re.search(r"\bno\b", ans.split("yes")[0][-6:])
                if pred_nt == str(r["gold"]["next_tool"]).lower():
                    ok_nt += 1
                if pred_pr == bool(r["gold"]["run_precheck"]):
                    ok_pr += 1
        n = len(test_rows_eval)
        print(f"[{tag}] test next_tool acc={ok_nt}/{n}={ok_nt/n:.3f}  precheck acc={ok_pr}/{n}={ok_pr/n:.3f}  "
              f"({n} rows, sampled from {len(rows)})", flush=True)
        if tag == "test BEFORE":
            print(f"[{tag}] baseline = untrained 30B-A3B on the gauntlet task", flush=True)
        model.config.use_cache = False  # back to training setting
        return {"next_tool": ok_nt / n, "precheck": ok_pr / n, "n": n}

    model.train()
    n_batches = len(train_enc)
    for ep in range(EPOCHS):
        random.shuffle(train_enc)
        for i in range(0, n_batches, BATCH):
            b = collate(train_enc[i:i + BATCH])
            ids, labels = b[0].to("cuda:0"), b[1].to("cuda:0")
            out = model(input_ids=ids, labels=labels)
            loss = out.loss / GRAD_ACCUM
            loss.backward()
            if (i // BATCH + 1) % GRAD_ACCUM == 0 or i + BATCH >= n_batches:
                opt.step()
                sched.step()
                opt.zero_grad()
            if (i // BATCH + 1) % 3 == 0:
                print(f"epoch {ep+1}/{EPOCHS} batch {i//BATCH+1}/{math.ceil(n_batches/BATCH)} "
                      f"loss {out.loss.item():.4f} lr {sched.get_last_lr()[0]:.2e} "
                      f"t={time.time()-t0:.0f}s peak_mem={torch.cuda.max_memory_allocated()/1024**3:.1f}GB", flush=True)
        torch.cuda.empty_cache()

    # SAVE FIRST: the 3h session cap can kill us mid-eval; the adapter is the
    # deliverable, evals are diagnostics.
    OUT_DIR = "/kaggle/working/out_tooluse_lora_30b_a3b"
    os.makedirs(OUT_DIR, exist_ok=True)
    model.save_pretrained(OUT_DIR)  # peft adapter: adapter_model.safetensors + adapter_config.json
    print("adapter saved ->", os.listdir(OUT_DIR), flush=True)

    after = evaluate(test_rows, "test AFTER")
    val_after = evaluate(val_rows[:2], "val AFTER")
    # re-save in case evals mutated anything
    model.save_pretrained(OUT_DIR)
    meta = {
        "model": MODEL_NAME, "epochs": EPOCHS, "lr": LR, "rank": RANK, "alpha": LORA_ALPHA,
        "batch": BATCH, "grad_accum": GRAD_ACCUM, "max_len": MAX_LEN, "seed": SEED,
        "qlora": "nf4+double_quant, bf16 compute",
        "test_after": after, "val_after": val_after,
        "train_time_s": round(time.time() - t0, 1),
    }
    with open(os.path.join(OUT_DIR, "lora_meta.json"), "w") as f:
        json.dump(meta, f, indent=2)
    print("Saved adapter ->", OUT_DIR, flush=True)
    print(json.dumps(meta, indent=2), flush=True)


if __name__ == "__main__":
    main()
